python3 -c "
import random
import time
from collections import defaultdict

def dinucleotide_shuffle_retry(seq: str, max_attempts=1000) -> str:
    if len(seq) < 2:
        return seq
    start_char = seq[0]
    transitions = defaultdict(list)
    for i in range(len(seq) - 1):
        transitions[seq[i]].append(seq[i+1])

    for attempt in range(max_attempts):
        shuffled_trans = {k: list(v) for k, v in transitions.items()}
        for k in shuffled_trans:
            random.shuffle(shuffled_trans[k])
        curr = start_char
        path = [curr]
        while shuffled_trans[curr]:
            next_node = shuffled_trans[curr].pop()
            path.append(next_node)
            curr = next_node
        if all(len(v) == 0 for v in shuffled_trans.values()):
            return ''.join(path)
    # fallback
    return seq

seq = 'GATTACAGATTACAGATTACAACGTACGTACGTACGTACGTACGTACGTACGTACGTACGTACGTACGTACGTACGTACGTACGT' * 2
print('Length of test sequence:', len(seq))
t0 = time.time()
for _ in range(1000):
    _ = dinucleotide_shuffle_retry(seq)
t1 = time.time()
print('Time for 1000 shuffles:', t1 - t0, 'seconds')
"

